(8353,0,25,0,0,'I\'m waiting...',0),
(8354,0,25,0,0,'I\'m waiting...',0),
(10496,1,1,0,0,'You\'re back, $N. You must tell me all about what you\'ve found out. But first let us arrange for your reward.',0),
