(11693,0,1,0,0,'Doesn\'t look like enough of the plagued magnataur have been put down yet, $c.$B$BThink you could take care of a few more before coming back?',26365),
(11694,0,1,0,0,'Time\'s wasting, $c. The last thing we need is to have to face plagued magnataur.$B$BThe normal ones are bad enough as it is!',26365),
(11698,0,1,0,0,'There\'s no way that you could have killed so many Scourge in such a short time!',26365),
(11719,0,5,0,0,'Don\'t be afraid.',32750),
(12036,0,6,0,0,'What\'s taking so long?',32750),
(12111,0,5,0,0,'You must protect the wildlife from the Scourge contagion!',32750),
(12138,0,1,0,0,'How\'s the charging going?',26822),
(12139,0,0,0,0,'The Horde\'s children need you!  Do not abandon them!',0),
