(12198,0,1,0,0,'Did you get that golem charged? Tormak is getting impatient again...',0),
(12301,0,6,0,0,'Is it done?',26365),
(12304,0,6,0,0,'Why is it that I doubt your sincerity when you suggest that you\'ve done all that you can to clear the shore of those ghosts?',32750),
(12415,0,1,0,0,'Have you cleared the area of horses?',0),
(12428,0,0,0,0,'It\'s not over until you or the furbolg tips over, friend!',0),
