(12430,0,0,0,0,'It\'s not over until... well, you know the drift by now.',0),
(12448,0,1,0,0,'I\'m glad you\'re still with us, $r.',32750),
(12449,0,1,0,0,'I started to worry that the Scourge in the shrine had claimed you. It is good that you yet live.',32750),
(12524,0,1,0,0,'Have you taught those thugs that we are not to be trifled with?',0),
(12613,0,0,0,0,'Is it done, $n?',0),
