(13051,0,0,0,0,'Hail, $n!',0),
(13056,0,0,0,0,'You find that dirty mongrel, $n?',0),
(13215,0,11,0,0,'I laugh at your efforts. You are not worthy to fight here.',0),
(13259,0,0,0,0,'For honor, $n.',0),
(13313,0,1,0,0,'Have you eliminated the Alliance\'s reconnaissance operations in the western part of the glacier?',0),
(13329,0,1,0,0,'Have you done as I asked?',0),
(13338,0,1,0,0,'Have you crippled Corp\'rethar\'s defenders?',26899),
(13356,0,0,0,0,'Well, $r? How\'d it turn out?',0),
(13411,0,0,0,0,'Return to me after you have helped capture each fort!',0),
(13569,0,0,0,0,'The great spirits have been here longer than I can remember. They were once mortal animals if all the stories are true, and they died in time of dire fates.',25996),
(13612,0,0,0,0,'Was your hunt successful, $r?',30706),
(13613,0,0,0,0,'Have you administered the salve to our fallen warriors, $r?',30706),
(13628,0,0,0,0,'Quite an entrance, $r. What can I do for you?',0),
(13644,0,33,0,0,'The harbinger yet lives, $n. I cannot begin to cleanse Lake Falathim until it is slain.',25996),
(13712,0,0,0,0,'Work complete!',30920),
(13730,0,0,0,0,'Did you fill up that canister for me, $c?',30920),
(13798,0,0,0,0,'Has the enemy fallen, $n?',30920),
(13801,0,0,0,0,'Did you rid the barrows of the ghosts?',30920),
(13806,0,0,0,0,'Have you managed to close the satyr portals, $r?',32028),
