(13890,0,0,0,0,'Well, $c...$b$bHave you done as I asked?',32028),
(13901,0,0,0,0,'Hello again, $r.$b$bHave you shown the naga the might of the Horde?',32028),
(13943,0,0,0,0,'Well, $r, have you taught the elves a little humility?',32028),
(13947,0,0,0,0,'Astranaar is burning!$b$bFor the Horde!',32028),
(13962,0,0,0,0,'Well, $r? Is Ordanus defeated?',32028),
