(26933,0,0,0,0,'For a bunch of combat-trained goons, they certainly have made some progress on that farm.',32638),
(26937,0,0,0,0,'Have you lost your way, $n?',32638),
(26953,0,0,0,0,'Zen\'Kiki needs a... a big $g brother: sister;, like you, to help him gain some confidence.',32638),
(26954,0,0,0,0,'Back so soon?',32638),
(26955,0,0,0,0,'By the grace of the Earthmother, I hope this works.',32638),
