(27085,0,0,0,0,'Dark Lady watch over you.',32638),
(27086,0,0,0,0,'You will find them to the west, $n.  Do not fail me.',32638),
(27088,0,6,0,0,'Have you dealt with the ettin?',0),
(27093,0,0,0,0,'Thankfully we\'re almost out of ale.',0),
(27094,0,6,0,0,'You killed the Skitterweb matriarch?',0),
(27095,0,0,0,0,'The matriarch must be found!',0),
(27097,0,0,0,0,'Victory!',0),
(27099,0,6,0,0,'What have you to report?',0),
(27117,0,0,0,0,'I will not rest until the Lich King\'s taint is lifted from Andorhal.',32638),
(27136,0,0,0,0,'Yes, $n?',0),
(27151,0,0,0,0,'Welcome back.',32638),
(27156,0,0,0,0,'I\'m not paying you to talk to me.  I\'m paying you to talk with my soldiers... and then fight with them.',32638),
(27157,0,0,0,0,'I need to get those drudges back to work.',32638),
(27178,0,273,0,0,'You\'re soaked, mate.',27326),
(27181,0,0,0,0,'You found the ambushers?',32305),
(27188,0,1,0,0,'What have you learned from the spirits haunting this place?',32305),
(27199,0,0,0,0,'You will find them to the east, $n.  Do not fail me.',25928),
(27210,0,1,0,0,'Have you driven the deserter agents from Theramore?',25996),
(27299,0,6,0,0,'Did ya have any luck with dose tentacles?',0),
(27300,0,1,0,0,'All over da highlands, da Twilight pervert da elements and turn dem against us. We\'ve witnessed unbearable horrors at dey\'re hands. I\'m eager to see dem slaughtered.',0),
(27311,0,1,0,0,'We shall have to burn more of their weapon racks than that if we are to put a dent in their ability to fight.',32305),
(27313,0,1,0,0,'We need to kill more of the Grimtotem, $n.',32305),
(27315,0,1,0,0,'The Gloomaxe must be slain if we are to effectively reduce the might of the Grimtotem attack on Freewind Post.',32305),
(27319,0,1,0,0,'We must kill Elder Stormhoof before we deal with the rest of the Grimtotem chiefs.',32305),
(27324,0,1,0,0,'$n, we must find and kill Grundig Darkcloud.',32305),
(27328,0,1,0,0,'Arnak must fall, $n, if we are to win the battle against the Grimtotem.',32305),
(27330,0,1,0,0,'Only by subduing Arikara will you discover where Magatha Grimtotem is hiding.',32305),
(27333,0,25,0,0,'Kill the rebels!',32305),
(27340,0,1,0,0,'Have you made any progress in stopping the Grimtotem attacks?',32305),
(27341,0,6,0,0,'What\'s the word out there, $n?',27326),
(27349,0,0,0,0,'Status?',32305),
(27360,0,0,0,0,'The 7th Legion must pay for what they did!',32305),
(27366,0,0,0,0,'You\'re still alive, $n.$B$BAre they?',27326),
(27371,0,0,0,0,'I can\'t wait to lay waste to these undead.  Boom!',32638),
