(27548,0,5,0,0,'Pyrewood Village must be reduced to ashes and our enemies slain!',32305),
(27550,0,274,0,0,'I feel no remorse.',32305),
(27580,0,1,0,0,'Marstone is a decorated field general. He will not go down easy.',32305),
