INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `EmoteOnCompleteDelay`, `EmoteOnIncompleteDelay`, `CompletionText`, `VerifiedBuild`) VALUES
(45261,0,0,0,0,'No matter what crises come up, we must stay the course and free my people from their addiction.$B$BWe take it one day at a time.',0),
(45262,0,0,0,0,'The message is almost ready.',0),
(45263,0,0,0,0,'Are you ready?',0),
(45265,0,0,0,0,'My people must be free.',0),
(45266,0,0,0,0,'Is it done?',0),
