(45268,0,0,0,0,'Are you ready?',0),
(45269,0,0,0,0,'Even if our failure means their doom, they deserve a taste of freedom, no matter how fleeting.',0),
(45316,0,0,0,0,'Now is the time for action!',0),
(45413,0,0,0,0,'We can\'t risk another attack until we get to the bottom of this.',0),
