(45863,0,0,0,0,'Are you ready?',0),
(46245,0,0,0,0,'Oi! Which building should we work on?$b$bI\'ve got deadlines to meet, mate!',27980),
(46246,0,6,0,0,'Did they plead for their lives?$b$bDid they whimper as they bled away to nothingness?',0),
